import React, { useState } from "react";
import axios from "axios";
import "../styles/Auth.css"; // Import common styles for both Signup and Login

const SignupPage = ({ onSwitchToLogin }) => {
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    password: "",
    userType: "",
  });

  const [error, setError] = useState("");

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!formData.name || !formData.phone || !formData.email || !formData.password || !formData.userType) {
      setError("All fields are required!");
      return;
    }

    try {
      const response = await axios.post("http://localhost:5001/api/auth/signup", formData);
      alert(response.data.message);
      setFormData({ name: "", phone: "", email: "", password: "", userType: "" });
    } catch (err) {
      setError(err.response?.data?.message || "Something went wrong! Please try again.");
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h2>Sign Up</h2>
        <form className="auth-form" onSubmit={handleSubmit}>
          <input type="text" name="name" placeholder="Full Name" value={formData.name} onChange={handleInputChange} required />
          <input type="text" name="phone" placeholder="Phone Number" value={formData.phone} onChange={handleInputChange} required />
          <input type="email" name="email" placeholder="Email Address" value={formData.email} onChange={handleInputChange} required />
          <input type="password" name="password" placeholder="Password" value={formData.password} onChange={handleInputChange} required />
          <select name="userType" value={formData.userType} onChange={handleInputChange} required>
            <option value="" disabled>Select User Type</option>
            <option value="owner">Owner</option>
            <option value="manager">Manager</option>
            <option value="lorry_manager">Lorry Manager</option>
          </select>

          {error && <p className="error-message">{error}</p>}

          <button type="submit" className="btn btn-primary">Sign Up</button>
        </form>
        <div className="switch-to-login">
          <p>Already have an account?</p>
          <button onClick={onSwitchToLogin}>Login Here</button>
        </div>
      </div>
    </div>
  );
};

export default SignupPage;
